{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, had only 15% oral bioavailability in humans, below the 20% threshold; this is the closest affirmative low-bioavailability evidence for a lipophilic ester prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a dodecyl ester of an amino-acid-derived structure, showed about 60% oral bioavailability in healthy volunteers, indicating that some long-chain amino-acid esters can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty ester prodrug, had 85 ± 15% absolute oral bioavailability in children, showing that long-chain ester prodrugs can be almost completely absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Valomaciclovir stearate, a long-chain fatty ester prodrug, achieved >60% oral bioavailability in humans, another example of a well-absorbed lipophilic ester prodrug.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is orlistat, a beta-lactone pancreatic lipase inhibitor designed for local gastrointestinal action with negligible systemic absorption. Although several long-chain ester prodrugs show high oral bioavailability, the closest low-bioavailability analog (laninamivir octanoate, 15%) and the recognized orlistat behavior support a prediction below the 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability record for orlistat is present in the supplied evidence.",
    "Most high-bioavailability records are for ester prodrugs that are hydrolyzed to systemically absorbable active drugs, not for beta-lactone lipase inhibitors.",
    "No absolute bioavailability study with intravenous comparison is available for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

